<?php
// Resolve the external source from the gallery so this page keeps all its URLs relative.
if (isset($_GET['source'])) {
    $gallery = file_get_contents(__DIR__ . '/index.php');
    $name = preg_quote(basename(__FILE__), '~');
    if (preg_match('~<li>\s*<div class="entry-title"><a href="' . $name . '".*?</li>~s', $gallery, $entry)
        && preg_match('~Inspired by Jon\x27s <a href="([^"]+)"~', $entry[0], $link)) {
        $url = html_entity_decode($link[1], ENT_QUOTES, 'UTF-8');
        if (parse_url($url, PHP_URL_SCHEME) === 'https') { header('Location: ' . $url, true, 302); exit; }
    }
    http_response_code(404); exit('Source post not found. Return to the gallery index.');
}
?>
