<style>
:root{--ink:#122c32;--paper:#f6efda;--mint:#bcdcc4;--copper:#b7532f;--line:#c4bca7}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Trebuchet MS",Verdana,sans-serif;line-height:1.55}a{color:inherit;text-underline-offset:4px}main{max-width:1150px;margin:auto;padding:28px}nav{display:flex;justify-content:space-between;gap:20px;font-size:12px;letter-spacing:1px;text-transform:uppercase;border-bottom:1px solid var(--line);padding-bottom:18px}.eyebrow{font-size:11px;letter-spacing:3px;text-transform:uppercase;font-weight:bold;color:var(--copper)}h1{font-family:Georgia,serif;font-weight:normal;letter-spacing:-3px;font-size:clamp(42px,6.8vw,80px);line-height:1.02;margin:20px 0}h2{font-family:Georgia,serif;font-weight:normal;font-size:30px;margin:0 0 15px}.intro{max-width:620px;font-size:17px}.hero{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:32px;padding:40px 0}.vault{background:var(--ink);position:relative;overflow:hidden;border-radius:50% 50% 8px 8px;aspect-ratio:1;box-shadow:12px 12px 0 var(--mint)}.vault img{width:100%;height:100%;object-fit:cover;transition:filter .6s;filter:grayscale(var(--gray,.4))}.vault .seal{position:absolute;bottom:22px;left:10%;right:10%;border:1px solid #bcdcc477;background:#122c32ec;color:var(--mint);text-align:center;padding:14px}.seal strong{display:block;font-family:Georgia,serif;font-size:26px}.dial{position:absolute;top:10px;right:10px;width:66px;height:66px;border-radius:50%;border:2px dashed var(--mint);display:grid;place-items:center;color:var(--mint);background:var(--ink);transition:transform .8s}.workshop{display:grid;grid-template-columns:1fr 1.15fr;gap:32px;border-top:2px solid var(--ink);padding:30px 0}.controls{padding-right:20px}label{display:block;font-weight:bold;margin:16px 0 8px}input[type=range]{width:100%;accent-color:var(--copper);min-height:30px}.options{display:grid;grid-template-columns:1fr 1fr;gap:8px}.option{margin:0;border:1px solid var(--line);padding:11px;font-size:14px;font-weight:normal}.option input{accent-color:var(--ink);width:18px;height:18px;vertical-align:middle}.output{padding:25px;background:var(--ink);color:var(--paper);border-radius:4px}.output .eyebrow{color:var(--mint)}#password{display:block;min-height:95px;overflow-wrap:anywhere;font-family:"Courier New",monospace;font-size:24px;line-height:1.6;letter-spacing:1px;margin:14px 0}button{font:inherit;cursor:pointer;border:1px solid var(--ink);border-radius:2px;padding:12px 18px;background:var(--mint);color:var(--ink);min-height:48px;font-weight:bold}button:hover{filter:brightness(.94)}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid var(--copper);outline-offset:4px}button:disabled{opacity:.55;cursor:default}.actions{display:flex;gap:10px;flex-wrap:wrap}.secondary{background:transparent;border-color:var(--mint);color:var(--mint)}.micro{font-size:12px;opacity:.85}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin:25px 0}.stat{border-left:2px solid var(--copper);padding-left:16px}.stat strong{display:block;font-family:Georgia,serif;font-size:32px;font-weight:normal}.stat small{font-size:12px}.scale{height:13px;background:#dbd3bf;position:relative;margin:18px 0}.scale span{height:100%;display:block;background:var(--copper);transition:width .4s}.explainer{padding:20px;background:#e7e0c9;border-left:4px solid var(--copper)}.challenge{border-top:2px solid var(--ink);padding:32px 0}.challengehead{display:flex;justify-content:space-between;gap:20px;align-items:baseline}.choices{display:grid;grid-template-columns:1fr 1fr;gap:16px}.choice{background:transparent;text-align:left;padding:22px;border:1px solid var(--line);font-weight:normal}.choice strong{display:block;font-family:Georgia,serif;font-size:24px;margin:8px 0}.choice.chosen{background:var(--mint);border-color:var(--ink)}#verdict{min-height:80px;padding:18px 0;max-width:780px}footer{border-top:1px solid var(--line);padding:25px 0;font-size:13px}.note{font-size:13px;max-width:750px}.status{min-height:20px;margin-top:12px;color:var(--mint);font-size:13px}@media(max-width:700px){main{padding:20px}.hero,.workshop{grid-template-columns:1fr;gap:24px}.hero{padding-top:24px}.vault{max-width:390px;width:100%;margin:auto}.controls{padding-right:0}.stats{gap:7px}.stat{padding-left:10px}.stat strong{font-size:25px}.choices{grid-template-columns:1fr}.challengehead{display:block}h1{letter-spacing:-2px}nav{font-size:10px}.output{padding:20px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}
