<body><main>
<nav><a href="./">← Chloe Reads Jon</a><span>Specimen No. 004 · Randomness</span></nav>
<section class="hero"><div><span class="eyebrow">A small museum of enormous numbers</span><h1>The Combination<br><em>Conservatory.</em></h1><p class="intro">A tiny change to a password can grow a truly ridiculous number of possibilities. Turn the dial. Grow a combination. See what randomness buys you.</p><p class="micro">Inspired by Jon’s discovery of KeePass in 2006.</p></div><figure class="vault" style="margin:0"><img src="data:image/webp;base64," alt="A mint-green seed-pod vault with a brass combination dial and little botanical sprouts"><div class="dial" aria-hidden="true">✦</div><figcaption class="seal"><span class="eyebrow" style="color:inherit">Your possibility garden</span><strong id="vaultLabel">Growing…</strong></figcaption></figure></section>
<section class="workshop" aria-label="Password workshop"><div class="controls"><span class="eyebrow">01 / Set the combination</span><h2>More room to be random.</h2><label for="length">Length <output id="lengthOut">18</output> characters</label><input id="length" type="range" min="6" max="40" value="18"><p class="micro">Choose the character sets allowed by your site.</p><div class="options">
<label class="option"><input type="checkbox" data-set="abcdefghijklmnopqrstuvwxyz" checked> Lowercase a–z</label>
<label class="option"><input type="checkbox" data-set="ABCDEFGHIJKLMNOPQRSTUVWXYZ" checked> Uppercase A–Z</label>
<label class="option"><input type="checkbox" data-set="0123456789" checked> Digits 0–9</label>
<label class="option"><input type="checkbox" data-set="!@#$%^&*()-_=+[]{}:,.?" checked> Symbols</label>
</div><p class="micro">Selected sets form the pool, not a promise that every set appears. Each character is sampled independently and uniformly.</p></div>
<div class="output"><span class="eyebrow">Generated here, in your browser</span><output id="password" aria-label="Generated password"></output><div class="actions"><button id="generate">Grow another ↻</button><button class="secondary" id="copy">Copy combination</button><button class="secondary" id="reveal" aria-pressed="true">Hide</button></div><div class="status" id="status" role="status" aria-live="polite"></div><p class="micro">Nothing is saved or sent. Use a unique password for each account and keep it in your password manager.</p></div></section>
<section aria-label="Randomness measurements"><div class="stats"><div class="stat"><strong id="pool">82</strong><small>possible characters</small></div><div class="stat"><strong id="bits">114</strong><small>bits of random entropy</small></div><div class="stat"><strong id="space">10³⁴</strong><small>possible combinations</small></div></div><div class="scale" aria-hidden="true"><span id="bar"></span></div><p class="explainer" id="comparison"></p><p class="note">This is a search-space illustration, not a security rating or a forecast. It assumes genuinely random characters and an attacker trying guesses offline. Real speed depends heavily on how a service stores passwords. Human-made patterns do not earn this entropy just by looking complicated.</p></section>
<section class="challenge"><div class="challengehead"><div><span class="eyebrow">02 / Try your intuition</span><h2>Which garden is bigger?</h2></div><span id="round" class="micro"></span></div><p id="question"></p><div class="choices"><button class="choice" id="a"></button><button class="choice" id="b"></button></div><div id="verdict" role="status" aria-live="polite">Choose a card to reveal the comparison. No stopwatch, no score.</div><button id="next" disabled>Next specimen →</button></section>
<footer>Inspired by Jon’s <a href="?source=1">Open-source password managers</a>. A little brass-and-botany experiment by Chloe.</footer>
</main><script>
'use strict';
const $=id=>document.getElementById(id);
let current='',visible=true;
function randomIndex(n){const ceiling=Math.floor(4294967296/n)*n;const sample=new Uint32Array(1);do{crypto.getRandomValues(sample)}while(sample[0]>=ceiling);return sample[0]%n}
function magnitude(log){if(log<3)return Math.round(10**log).toLocaleString();return '10^'+log.toFixed(1)}
function duration(logSeconds){if(logSeconds<0)return 'less than a second';if(logSeconds<Math.log10(60))return Math.round(10**logSeconds)+' seconds';if(logSeconds<Math.log10(3600))return Math.round(10**logSeconds/60)+' minutes';if(logSeconds<Math.log10(86400))return Math.round(10**logSeconds/3600)+' hours';if(logSeconds<Math.log10(31557600))return Math.round(10**logSeconds/86400)+' days';const years=logSeconds-Math.log10(31557600);return (years<6?Math.round(10**years).toLocaleString():magnitude(years))+' years'}
function showPassword(){$('password').textContent=visible?current:'•'.repeat(current.length)}
function update(){
 const pool=[...document.querySelectorAll('[data-set]:checked')].map(x=>x.dataset.set).join(''),length=+$('length').value;
 $('lengthOut').textContent=length;
 if(!pool.length){current='';$('password').textContent='Choose at least one character set.';$('copy').disabled=true;$('pool').textContent='0';$('bits').textContent='—';$('space').textContent='—';$('bar').style.width='0';$('comparison').textContent='An empty pool has no combinations. Pick a character set above.';$('vaultLabel').textContent='Awaiting a seed';return}
 const bits=length*Math.log2(pool.length),logSpace=length*Math.log10(pool.length);
 $('pool').textContent=pool.length;$('bits').textContent=bits.toFixed(1);$('space').textContent='10^'+logSpace.toFixed(1);
 $('bar').style.width=Math.min(100,bits/256*100)+'%';document.querySelector('.vault').style.setProperty('--gray',Math.max(0,1-bits/130));document.querySelector('.dial').style.transform='rotate('+length*19+'deg)';
 $('vaultLabel').textContent=bits.toFixed(0)+' bits in bloom';
 $('comparison').textContent='At an illustrative one billion guesses per second, searching half this space would take about '+duration(logSpace-Math.log10(2)-9)+'. Add one character and the space multiplies by '+pool.length+'.';
 $('status').textContent='';
 try{if(!globalThis.crypto?.getRandomValues)throw Error('missing');current=Array.from({length},()=>pool[randomIndex(pool.length)]).join('');$('copy').disabled=false;showPassword()}catch(e){current='';$('password').textContent='Secure randomness is unavailable in this browser.';$('copy').disabled=true}
}
document.querySelectorAll('[data-set]').forEach(el=>el.addEventListener('change',update));$('length').addEventListener('input',update);$('generate').addEventListener('click',update);
$('reveal').addEventListener('click',()=>{visible=!visible;$('reveal').textContent=visible?'Hide':'Show';$('reveal').setAttribute('aria-pressed',String(visible));if(current)showPassword()});
$('copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(current);$('status').textContent='Copied. Paste it into your password manager.'}catch(e){$('status').textContent='Clipboard unavailable. Use Show, then select the combination to copy it.'}});
const rounds=[
{q:'Both are chosen uniformly at random. Which has more possibilities?',a:['6 random symbols','94 possible characters at each position'],b:['12 random lowercase letters','26 possible characters at each position'],win:1,why:'Length wins here: 6 × log₂(94) ≈ 39 bits; 12 × log₂(26) ≈ 56 bits. That is roughly 138,000 times as many possibilities.'},
{q:'A longer number, or a shorter mixed combination?',a:['16 random digits','10 possible characters per position'],b:['8 random letters & digits','62 possible characters per position'],win:0,why:'The random digits win: about 53 bits versus 48 bits. Numbers are not inherently weak; a short or predictable number is the problem.'},
{q:'A familiar word dressed up, or a genuine random draw?',a:['Password1!','A common word with predictable substitutions'],b:['12 random lowercase letters','A fresh, independent draw every time'],win:1,why:'The random draw wins. Attackers try familiar words and common modifications early. Character variety cannot turn a predictable recipe into random entropy.'},
{q:'Which pool creates more possibilities?',a:['20 random lowercase letters','26 choices at each position'],b:['20 random lowercase letters & digits','36 choices at each position'],win:1,why:'The second space is (36/26)²⁰ ≈ 671 times larger. Both are enormous when genuinely random. Extra length and extra character choices each multiply the space.'}
];let r=0,answered=false;
function draw(){answered=false;const item=rounds[r];$('round').textContent='SPECIMEN '+(r+1)+' / '+rounds.length;$('question').textContent=item.q;['a','b'].forEach(key=>{const el=$(key);el.replaceChildren();const strong=document.createElement('strong');strong.textContent=item[key][0];const small=document.createElement('span');small.textContent=item[key][1];el.append(strong,small);el.classList.remove('chosen');el.disabled=false;el.setAttribute('aria-pressed','false')});$('verdict').textContent='Choose a card to reveal the comparison. No stopwatch, no score.';$('next').disabled=true;$('next').textContent=r===rounds.length-1?'Explore again ↻':'Next specimen →'}
['a','b'].forEach((key,i)=>$(key).addEventListener('click',()=>{if(answered)return;answered=true;$(key).classList.add('chosen');$(key).setAttribute('aria-pressed','true');$('verdict').textContent=(i===rounds[r].win?'Exactly. ':'A useful surprise! ')+rounds[r].why;$('next').disabled=false}));
$('next').addEventListener('click',()=>{r=(r+1)%rounds.length;draw()});update();draw();
</script></body></html>
